
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_x_n12_sx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_x_n12_sx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.928943011230565e+00, -2.894719386861916e+00, -2.846094343915206e+00, -2.777257772183554e+00, -2.680112397484071e+00, -2.543028060013514e+00, -2.348020354887294e+00, -2.064951027042734e+00, -1.653036096870822e+00, -1.166727438596082e+00, -8.914947377520754e-01, -5.159701370583317e-01, -4.223335650723571e-01, -3.732821923505899e-01, -2.988279164194880e-01, -2.271411294537227e-01, -1.410046885916357e-01, -8.443841676036641e-02, -2.803996344289248e-02, -3.486153205417538e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


